function setSelectByText(id, text) {
  const el = document.getElementById(id);
  const opt = Array.from(el.options).find(o => o.text.trim() === text);
  if (!opt) return {id, error: 'option not found', available: Array.from(el.options).map(o=>o.text)};
  el.value = opt.value;
  el.dispatchEvent(new Event('change', {bubbles:true}));
  return {id, set: opt.text};
}
