const text = '成為一個領導人，最重要的就是如何學會跟夥伴溝通。因為很多時候領導人的溝通不到位、講出來的話夥伴理解不了，以至於無法讓夥伴們真正去執行領導人的任務。所以學習有效溝通以及如何溝通，我們要上升為領導人的溝通藝術，這是夥伴們最需要學習的一堂課。';
CKEDITOR.instances['eventDetls'].setData('<p>' + text + '</p>');
CKEDITOR.instances['eventDetls'].updateElement();
document.getElementById('eventDetls').value;

document.getElementById('submitBTN').click();
await new Promise(r=>setTimeout(r,1500));
document.body.innerText.match(/復審活動詳情[\s\S]{0,450}/)?.[0] || document.body.innerText.slice(0,300);

document.getElementById('confirmBTN').click();
await new Promise(r=>setTimeout(r,1500));
'clicked';

