'done';

async function search(q){
  const input = Array.from(document.querySelectorAll('input[type="text"]')).find(i=>i.offsetParent!==null);
  input.value = q;
  input.dispatchEvent(new Event('keyup', {bubbles:true}));
  await new Promise(r=>setTimeout(r,500));
  const rows = Array.from(document.querySelectorAll('table tbody tr'));
  return rows.map(r=>r.innerText.replace(/\n/g,' | ').trim()).filter(t=>t && !t.includes('大台南南區') && !t.includes('顯示') && !t.includes('創建'));
}
const r1 = await search('初階MSP');
const r2 = await search('進階MSP');
const r3 = await search('期中訓');
[r1,r2,r3];

